effect.shader:
float gmHash21(vec2 p) {
return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}
void main() {
vec2 uv = acScreenNorm;
vec2 texSize = max(inputImg.size, vec2(1.0));
vec2 manualMotion = vec2(cos(angle), sin(angle)) * distancePx / texSize;
vec2 velocityMotion = acVelocity * velocityScale / max(acScreenSize, vec2(1.0));
vec2 trailVector = useLayerVelocity ? velocityMotion : manualMotion;
if (length(trailVector) < 0.000001) {
trailVector = manualMotion;
}
vec4 src = texture2DCv(inputImg.texture, uv);
vec3 trailRgb = vec3(0.0);
float trailAlpha = 0.0;
float normalization = 0.0;
float sampleWeight = 1.0;
float safeSize = max(particleSizePx, 1.0);
for (int i = 0; i < 24; i++) {
float enabled = step(float(i) + 0.5, particleCount);
float t = float(i + 1) / max(particleCount, 1.0);
vec2 sampleUv = uv - trailVector * t;
vec2 particleCoord = sampleUv * texSize / safeSize;
vec2 cell = floor(particleCoord);
vec2 local = fract(particleCoord) - 0.5;
float randomValue = gmHash21(cell + vec2(float(i) * 1.73 + seed, evolution * 3.17));
float selected = step(1.0 - density, randomValue);
float circle = 1.0 - smoothstep(0.22, 0.5, length(local));
float particleMask = selected * circle * enabled;
vec4 sampleColor = texture2DCv(inputImg.texture, clamp(sampleUv, 0.0, 1.0));
vec3 tinted = mix(sampleColor.rgb, trailColor.rgb * sampleColor.a, colorMix);
trailRgb += tinted * particleMask * sampleWeight;
trailAlpha += sampleColor.a * particleMask * sampleWeight;
normalization += particleMask * sampleWeight;
sampleWeight *= decay;
}
vec3 particles = trailRgb / max(normalization, 0.0001);
float particlesAlpha = clamp(trailAlpha / max(normalization, 0.0001) * strength, 0.0, 1.0);
vec3 resultRgb;
if (blendMode == 1) {
resultRgb = src.rgb + particles * particlesAlpha;
} else if (blendMode == 2) {
resultRgb = src.rgb + particles * particlesAlpha * (1.0 - src.a);
} else {
vec3 screenColor = 1.0 - (1.0 - src.rgb) * (1.0 - clamp(particles, 0.0, 1.0));
resultRgb = mix(src.rgb, screenColor, particlesAlpha);
}
float resultAlpha = src.a + particlesAlpha * (1.0 - src.a);
gl_FragColor = vec4(resultRgb, resultAlpha);
gl_FragColor *= texture2DCv(inputImg.texture, acScreenNorm).a;
}
